      `<g class="sn-on">${txt('ON', 6, 5, 14, MONO, { w: 700, f: '#fff', a: 'middle' })}</g><g class="sn-off">${txt('OFF', 6, 5, 14, MONO, { w: 700, f: '#FFD9D2', a: 'middle' })}</g>` +
      `</g>`

    // =====================================================================================
    // LINED SHEET with "VIBES"
    // =====================================================================================
    const PW = 540
    const PH = 330
    const sheetD = `M2 3L${PW - 4} 0L${PW} ${PH}L0 ${PH - 3}Z`
    let rules = ''
