        const y = 40 + r() * 700
        const d = 14 + r() * 16
        motes += `<g transform="translate(${n(x)} ${n(y)})"><circle class="sn-mote" style="animation-duration:${n(d)}s;animation-delay:${n(-r() * d)}s" r="${n(1 + r() * 1.8)}" fill="#FFE9C4"/></g>`
