          tk('psF' + i, p => p.k[i], 0.6 / dY, v => `scale:1 ${n3(v)}`, 'psSy' + i, v => ty(v * dY)) +
          tk('psSr' + i, p => p.str[i][2], 0.13, v => `rotate:${Math.round(v * 100) / 100}deg`)
