    const cars1 = carOn([-0.5, -3], [-0.5, 42], 26, -4, RED, true) + carOn([-1.5, 42], [-1.5, -3], 30, -19, YEL, true, true) + carOn([-0.5, -3], [-0.5, 42], 26, -15, TEAL, true) + carOn([-1.5, 42], [-1.5, -3], 30, -7, NAVY, true)
