    ':': [0, 0, 4, 0, 4, 0, 0], '.': [0, 0, 0, 0, 0, 0, 4], '-': [0, 0, 0, 31, 0, 0, 0], '*': [0, 4, 21, 14, 21, 4, 0], '>': [8, 4, 2, 1, 2, 4, 8], '/': [1, 1, 2, 4, 8, 16, 16],
